"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["99843"],{42165(e){e.exports=JSON.parse('{"id":"FIN-868","slug":"fintech","term":"Fintech","also_known_as":[],"difficulty":"Beginner","definition":"Fintech, short for financial technology, refers to the use of technology to deliver, improve or automate financial services, and to the companies that provide such services.","explanation":["Fintech covers a wide range of products and services. Examples include mobile banking apps, digital payment services, peer-to-peer lending platforms, robo-advisors, online insurance, crowdfunding platforms, buy now pay later services, cryptocurrency exchanges and software that helps businesses manage their finances.","Fintech companies range from small start-ups to large technology firms, and traditional banks and insurers also invest heavily in technology. Many fintech companies focus on improving the customer experience, lowering costs or serving groups that traditional financial institutions have underserved.","For example, a fintech company might offer international money transfers at lower fees and better exchange rates than traditional banks, using its own technology and network of accounts.","Fintech has increased competition, convenience and access to financial services worldwide, particularly through mobile payments in developing countries. It also raises challenges for regulators, including consumer protection, data privacy, cybersecurity and ensuring that new firms meet the same standards as traditional institutions. Some regulators have created sandboxes, which allow fintech firms to test new products under supervision before launching them fully."],"note":"","total":1500,"prev":{"slug":"finished-goods","term":"Finished Goods"},"next":{"slug":"fiscal-multiplier","term":"Fiscal Multiplier"}}')}}]);